import type { Quiz } from "./types";

export const leasesQuiz: Quiz = {
  key: "leases",
  title: "Leases",
  subtitle: "Lessee and lessor accounting under ASC 842",
  discipline: "far",
  course: "cpa",
  questions: [
    {
      id: "8718",
      prompt: `Harris Inc. leased equipment under a finance lease for a period of seven years, contracting to pay $100,000 rent in advance at the start of the lease term on December 31, Year 1, and $100,000 annually on December 31 of each of the next six years. The present value at December 31, Year 1, of the seven rent payments over the lease term discounted at 10% (the implicit interest rate) was $535,000. Harris amortizes its liability using the effective interest method. In its December 31, Year 2, balance sheet, Harris should report a lease liability of:`,
      choices: [
        `$437,350`,
        `$378,500`,
        `$391,500`,
        `$500,000`,
      ],
      correctIndex: 1,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">B. $378,500 is correct.</strong> The payment at commencement is all principal, so Year 2 interest accrues on $435,000, not $535,000.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">A lease liability is recorded at the <strong style="color:var(--mx-navy)">present value of the lease payments</strong> (<strong style="color:var(--mx-navy)">ASC 842</strong>) and then amortizes exactly like a loan. Under the <strong style="color:var(--mx-navy)">effective interest method</strong>, interest expense equals the beginning liability times the implicit rate, and the cash payment reduces the liability by whatever is left after covering that interest.</p><p style="margin:0 0 18px">The trap here is timing. Rent is paid <strong style="color:var(--mx-navy)">in advance</strong>, so the first $100,000 changes hands on the commencement date, December 31, Year 1, before any time has passed. No interest has accrued yet, so that payment is <strong style="color:var(--mx-navy)">entirely principal</strong> and the liability falls immediately to $435,000. That balance, not the original $535,000, is what earns 10% during Year 2.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The math</h3><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:8px 10px; margin-bottom:18px"><table style="border:0; border-collapse:collapse; width:100%"><tbody><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Present value at December 31, Year 1</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$535,000</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Less: payment at commencement</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">(100,000)</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Balance carried into Year 2</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">435,000</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Interest for Year 2, $435,000 x 10%</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">43,500</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Less: payment on December 31, Year 2</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">(100,000)</td></tr><tr><td style="border:0; padding:11px 14px"><strong style="color:var(--mx-navy)">Lease liability at December 31, Year 2</strong></td><td style="border:0; padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">$378,500</strong></td></tr></tbody></table></div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The entry at December 31, Year 2</h3><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:8px 10px; margin-bottom:18px"><table style="border:0; border-collapse:collapse; width:100%"><tbody><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px"><strong style="color:var(--mx-navy)">Account</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Debit</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Credit</strong></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Interest expense</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$43,500</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Lease liability</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">56,500</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td></tr><tr><td style="border:0; padding:11px 14px 11px 40px">Cash</td><td style="border:0; padding:11px 14px; text-align:right"></td><td style="border:0; padding:11px 14px; text-align:right">$100,000</td></tr></tbody></table></div><p style="margin:0 0 12px">Only <strong style="color:var(--mx-navy)">$56,500 of the second payment is principal</strong>, which is why the liability does not drop by a full $100,000. Amortization of the <strong style="color:var(--mx-navy)">right-of-use asset</strong> is recorded separately and never touches the liability balance. Year 3 interest would be 10% of $378,500, and the pattern repeats until the final payment brings the liability to zero. The reported balance also equals the present value of the five payments still outstanding.</p></div>`,
    },
    {
      id: "5004",
      prompt: `On January 2 of the current year, Cole Co. signed an eight-year noncancelable lease for a new machine, requiring $15,000 annual payments at the beginning of each year. The machine has a useful life of 12 years, with no salvage value. Title passes to Cole at the lease expiration date. Cole use straight-line depreciation for all of its plant assets. Aggregate lease payments have a present value on January 2 of $108,000, based on an appropriate rate of interest. For the current year, Cole should record depreciation (amortization) expense for the leased machine at:`,
      choices: [
        `$0`,
        `$9,000`,
        `$13,500`,
        `$15,000`,
      ],
      correctIndex: 1,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">B. $9,000 is correct.</strong> Title passes to Cole, so the $108,000 capitalized asset is written off over the machine's 12-year useful life, not the 8-year lease term.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">A lease that <strong style="color:var(--mx-navy)">transfers ownership</strong> to the lessee is a <strong style="color:var(--mx-navy)">finance lease</strong> (<strong style="color:var(--mx-navy)">ASC 842</strong>). The lessee records a right-of-use asset and a lease liability at the <strong style="color:var(--mx-navy)">present value of the lease payments</strong>, here $108,000, and depreciates that amount, not the $120,000 of undiscounted cash payments.</p><p style="margin:0 0 18px">The amortization period is the trap. When title transfers or a purchase option is reasonably certain to be exercised, the lessee will still own the asset after the lease ends, so the asset is depreciated over its <strong style="color:var(--mx-navy)">useful life</strong>. Only when ownership does not transfer is the shorter <strong style="color:var(--mx-navy)">lease term</strong> used. With no salvage value and straight-line depreciation, the full $108,000 is spread over 12 years.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The math</h3><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:8px 10px; margin-bottom:18px"><table style="border:0; border-collapse:collapse; width:100%"><tbody><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Present value of lease payments, capitalized</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$108,000</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Salvage value</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$0</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Depreciable life, title transfers</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">12 years</td></tr><tr><td style="border:0; padding:11px 14px"><strong style="color:var(--mx-navy)">Annual expense, $108,000 / 12</strong></td><td style="border:0; padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">$9,000</strong></td></tr></tbody></table></div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The entries</h3><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:8px 10px; margin-bottom:18px"><table style="border:0; border-collapse:collapse; width:100%"><tbody><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px"><strong style="color:var(--mx-navy)">Account</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Debit</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Credit</strong></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Right-of-use asset</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$108,000</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px 11px 40px">Lease liability</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$108,000</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Depreciation expense</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$9,000</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td></tr><tr><td style="border:0; padding:11px 14px 11px 40px">Accumulated depreciation</td><td style="border:0; padding:11px 14px; text-align:right"></td><td style="border:0; padding:11px 14px; text-align:right">$9,000</td></tr></tbody></table></div><p style="margin:0 0 12px">The $15,000 annual payment is split between <strong style="color:var(--mx-navy)">interest</strong> and <strong style="color:var(--mx-navy)">principal</strong> on the liability and never touches the depreciation calculation.</p></div>`,
    },
    {
      id: "5006",
      prompt: `Oak Co. leased equipment for its entire nine-year useful life, agreeing to pay $50,000 at the start of the lease term on December 31, Year 1, and $50,000 annually on each December 31 for the next eight years. The present value on December 31, Year 1, of the nine lease payments over the lease term, using the rate implicit in the lease which Oak knows to be 10%, was $316,500. The December 31, Year 1, present value of the lease payments using Oak's incremental borrowing rate of 12% was $298,500. Oak made a timely second lease payment.

What amount should Oak report as a lease liability in its December 31, Year 2, balance sheet?`,
      choices: [
        `$350,000`,
        `$243,150`,
        `$228,320`,
        `$0`,
      ],
      correctIndex: 1,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">B. $243,150 is correct.</strong> Start with the $316,500 present value, subtract the payment made at commencement, add a year of interest at 10%, then subtract the second payment.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">Video walkthrough</h3><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:13px 18px; margin-bottom:18px"><video controls="controls" src="https://coursemaxwellcpareview.com/uploads/2025/07/07/17013-f.mp4" style="max-width:700px">Your browser does not support the video tag.</video></div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">A lessee discounts the lease payments at the <strong style="color:var(--mx-navy)">rate implicit in the lease</strong> whenever that rate is known (<strong style="color:var(--mx-navy)">ASC 842</strong>). Oak knows the implicit rate is 10%, so the $316,500 figure is used and the $298,500 computed at the incremental borrowing rate is ignored.</p><p style="margin:0 0 18px">Payments here are an <strong style="color:var(--mx-navy)">annuity due</strong>: the first $50,000 is paid on the commencement date itself, so it carries <strong style="color:var(--mx-navy)">no interest</strong> and reduces the liability immediately. After that, the liability is rolled forward each year using the <strong style="color:var(--mx-navy)">effective interest method</strong>: prior balance, plus interest at 10%, less the cash payment.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The math</h3><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:8px 10px; margin-bottom:18px"><table style="border:0; border-collapse:collapse; width:100%"><tbody><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Initial liability at 10%, December 31, Year 1</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$316,500</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Less: payment made at commencement</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">(50,000)</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Balance carried through Year 2</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">266,500</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Add: interest, $266,500 x 10%</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">26,650</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Less: second payment, December 31, Year 2</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">(50,000)</td></tr><tr><td style="border:0; padding:11px 14px"><strong style="color:var(--mx-navy)">Lease liability, December 31, Year 2</strong></td><td style="border:0; padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">$243,150</strong></td></tr></tbody></table></div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The second payment entry</h3><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:8px 10px; margin-bottom:18px"><table style="border:0; border-collapse:collapse; width:100%"><tbody><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px"><strong style="color:var(--mx-navy)">Account</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Debit</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Credit</strong></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Interest expense</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$26,650</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Lease liability</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">23,350</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td></tr><tr><td style="border:0; padding:11px 14px 11px 40px">Cash</td><td style="border:0; padding:11px 14px; text-align:right"></td><td style="border:0; padding:11px 14px; text-align:right">$50,000</td></tr></tbody></table></div><p style="margin:0">The lease runs for the asset's <strong style="color:var(--mx-navy)">entire nine-year useful life</strong>, so this is a <strong style="color:var(--mx-navy)">finance lease</strong>, but the liability rollforward would be identical under an operating lease.</p></div>`,
    },
    {
      id: "8708",
      prompt: `On December 31, Year 1, Neal Inc. leased machinery with a fair value of $105,000 from Frey Rentals Co. The agreement is a six‐year noncancelable lease requiring annual payments of $20,000 beginning December 31, Year 1. The lease is accounted for as a finance lease. Neal's incremental borrowing rate is 11%, and the interest rate implicit in the lease payments is 10%. The present value of an annuity due of 1 for 6 years at 10% is 4.7908, and at 11% is 4.6959.
      

      
        In its December 31, Year 1 balance sheet, Neal should report a lease liability of:`,
      choices: [
        `$93,918`,
        `$95,816`,
        `$75,816`,
        `$85,000`,
      ],
      correctIndex: 2,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">C. $75,816 is correct.</strong> The December 31 payment is made on the day the lease begins, so only the five remaining payments sit in the liability.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">Measure the lease liability at the <strong style="color:var(--mx-navy)">present value of the lease payments</strong>, discounted at the <strong style="color:var(--mx-navy)">rate implicit in the lease</strong> when the lessee can readily determine it (<strong style="color:var(--mx-navy)">ASC 842</strong>). Here the implicit rate of 10% is given, so the 11% incremental borrowing rate is never used.</p><p style="margin:0 0 18px">Payments begin at commencement, which makes this an <strong style="color:var(--mx-navy)">annuity due</strong>, so the 4.7908 factor applies; an ordinary annuity factor would understate the payments' value. The first $20,000 is paid on December 31, Year 1 and is <strong style="color:var(--mx-navy)">never discounted</strong>: it enters the initial measurement and then immediately reduces the liability when the cash goes out. The balance sheet figure is always the present value of the payments <strong style="color:var(--mx-navy)">still owed</strong>.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The math</h3><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:8px 10px; margin-bottom:18px"><table style="border:0; border-collapse:collapse; width:100%"><tbody><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Annual payment</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$20,000</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">PV factor, annuity due, 6 years at 10%</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">4.7908</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Initial lease liability, $20,000 x 4.7908</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$95,816</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Less payment made December 31, Year 1</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">(20,000)</td></tr><tr><td style="border:0; padding:11px 14px"><strong style="color:var(--mx-navy)">Lease liability reported at December 31, Year 1</strong></td><td style="border:0; padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">$75,816</strong></td></tr></tbody></table></div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The entries at December 31, Year 1</h3><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:8px 10px; margin-bottom:18px"><table style="border:0; border-collapse:collapse; width:100%"><tbody><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px"><strong style="color:var(--mx-navy)">Account</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Debit</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Credit</strong></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Right-of-use asset</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$95,816</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px 11px 40px">Lease liability</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$95,816</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Lease liability</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$20,000</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td></tr><tr><td style="border:0; padding:11px 14px 11px 40px">Cash</td><td style="border:0; padding:11px 14px; text-align:right"></td><td style="border:0; padding:11px 14px; text-align:right">$20,000</td></tr></tbody></table></div><p style="margin:0 0 12px">The right-of-use asset also starts at $95,816 because there are no initial direct costs, prepayments or incentives to adjust, and that $95,816 is below the $105,000 fair value, so fair value does not cap the measurement.</p><p style="margin:0">Because the payment occurs on day one, no time has passed and none of it is interest: the whole $20,000 is <strong style="color:var(--mx-navy)">principal</strong>. Interest expense first appears in Year 2, accruing at 10% on the $75,816 carrying amount.</p></div>`,
    },
    {
      id: "9450",
      prompt: `On January 1, Year 1, Apex Manufacturing leased a piece of equipment from the lessor with the following pertinent information:

	Lease Term: 4 years

	Annual Lease Payment (made at the end of each year): $150,000

	Useful Life of Equipment: 8 years

	Implicit Interest Rate in Lease (known by Apex Manufacturing): 6%

	Present Value Factor of an Ordinary Annuity for 4 Years at 6%: 3.4651

What is the carrying value of the lease as of December 31, Year 2?`,
      choices: [
        `$400,951`,
        `$275,008`,
        `$324,560`,
        `$550,415`,
      ],
      correctIndex: 1,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">B. $275,008 is correct.</strong> Two payments have been applied to a $519,765 opening liability, each reducing it by the payment less that year's interest.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">A lessee records the lease liability at the <strong style="color:var(--mx-navy)">present value of the remaining lease payments</strong> and then carries it using the <strong style="color:var(--mx-navy)">effective interest method</strong> (<strong style="color:var(--mx-navy)">ASC 842</strong>). Each year interest accrues on the <strong style="color:var(--mx-navy)">beginning balance</strong> at the rate implicit in the lease, and the cash payment covers that interest first. Whatever is left reduces principal, so the carrying value at any date is the balance after the latest payment has been applied.</p><p style="margin:0 0 18px">Because the payments fall at the <strong style="color:var(--mx-navy)">end of each year</strong>, the ordinary annuity factor of 3.4651 is the correct one, and the <strong style="color:var(--mx-navy)">6% implicit rate</strong> is used because Apex knows it. The 8-year useful life is a distractor here: it drives amortization of the <strong style="color:var(--mx-navy)">right-of-use asset</strong>, never the liability balance.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The math</h3><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:8px 10px; margin-bottom:18px"><table style="border:0; border-collapse:collapse; width:100%"><tbody><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Annual lease payment</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$150,000</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">PV factor, ordinary annuity, 4 years, 6%</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">x 3.4651</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Initial liability, January 1, Year 1</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$519,765</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Year 1 interest, $519,765 x 6%</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$31,186</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Year 1 principal, $150,000 less $31,186</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">($118,814)</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Balance, December 31, Year 1</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$400,951</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Year 2 interest, $400,951 x 6%</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$24,057</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Year 2 principal, $150,000 less $24,057</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">($125,943)</td></tr><tr><td style="border:0; padding:11px 14px"><strong style="color:var(--mx-navy)">Carrying value, December 31, Year 2</strong></td><td style="border:0; padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">$275,008</strong></td></tr></tbody></table></div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The entry at December 31, Year 2</h3><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:8px 10px; margin-bottom:18px"><table style="border:0; border-collapse:collapse; width:100%"><tbody><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px"><strong style="color:var(--mx-navy)">Account</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Debit</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Credit</strong></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Interest expense</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$24,057</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Lease liability</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$125,943</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td></tr><tr><td style="border:0; padding:11px 14px 11px 40px">Cash</td><td style="border:0; padding:11px 14px; text-align:right"></td><td style="border:0; padding:11px 14px; text-align:right">$150,000</td></tr></tbody></table></div><p style="margin:0 0 12px">Interest falls each year as the balance shrinks, so more of every $150,000 payment attacks principal: $118,814 in Year 1, then $125,943 in Year 2. The remaining $275,008 is retired by the final two payments. The right-of-use asset follows a separate path, straight-line amortization over the 4-year lease term, so the two balances will not match after Year 1.</p></div>`,
    },
    {
      id: "9452",
      prompt: `On January 1, Year 1, Delta Corp entered into a lease agreement for industrial equipment with the following details:

	Lease Term: 4 years

	Annual Lease Payment (made at the end of each year): $80,000

	Useful Life of Equipment: 7 years

	Guaranteed Residual Value at the end of the Lease Term: $20,000

	Implicit Interest Rate in Lease (known by Delta Corp): 5%

	Present Value Factor of an Ordinary Annuity for 4 Years at 5%: 3.5460

	Present Value Factor of a Lump Sum for 4 Years at 5%: 0.8227

What is the interest expense related to the lease for the first year?`,
      choices: [
        `$15,007`,
        `$14,184`,
        `$15,500`,
        `$14,281`,
      ],
      correctIndex: 0,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">A. $15,007 is correct.</strong> Interest is the opening lease liability of $300,134 times the 5% implicit rate.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">Year 1 interest expense equals the <strong style="color:var(--mx-navy)">carrying amount of the lease liability at commencement</strong> multiplied by the <strong style="color:var(--mx-navy)">discount rate</strong>, here the implicit rate of 5% because Delta knows it. Payments at the end of each year form an <strong style="color:var(--mx-navy)">ordinary annuity</strong>, so no payment reduces the balance before interest accrues for the first full year.</p><p style="margin:0 0 18px">The trap is the residual. A <strong style="color:var(--mx-navy)">guaranteed residual value</strong> is an amount the lessee is obligated to make good at lease end, so its present value is part of the lease payments and belongs in the liability (<strong style="color:var(--mx-navy)">ASC 842</strong>). It is a <strong style="color:var(--mx-navy)">single sum</strong> due in four years, so discount it with the lump sum factor, not the annuity factor. An <strong style="color:var(--mx-navy)">unguaranteed</strong> residual would be excluded entirely.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The math</h3><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:8px 10px; margin-bottom:18px"><table style="border:0; border-collapse:collapse; width:100%"><tbody><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">PV of payments, $80,000 x 3.5460</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$283,680</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">PV of guaranteed residual, $20,000 x 0.8227</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">16,454</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Lease liability, January 1, Year 1</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$300,134</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Implicit rate</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">5%</td></tr><tr><td style="border:0; padding:11px 14px"><strong style="color:var(--mx-navy)">Year 1 interest expense</strong></td><td style="border:0; padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">$15,007</strong></td></tr></tbody></table></div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The entry at December 31, Year 1</h3><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:8px 10px; margin-bottom:18px"><table style="border:0; border-collapse:collapse; width:100%"><tbody><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px"><strong style="color:var(--mx-navy)">Account</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Debit</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Credit</strong></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Interest expense</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$15,007</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Lease liability</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">64,993</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td></tr><tr><td style="border:0; padding:11px 14px 11px 40px">Cash</td><td style="border:0; padding:11px 14px; text-align:right"></td><td style="border:0; padding:11px 14px; text-align:right">$80,000</td></tr></tbody></table></div><p style="margin:0 0 12px">The liability carries forward at <strong style="color:var(--mx-navy)">$235,141</strong>, and Year 2 interest is computed on that new balance.</p></div>`,
    },
    {
      id: "8710",
      prompt: `On April 1, Year 1, Hall Fitness Center leased its gym to Dunn Fitness Center under a four‐year operating lease. Hall normally charges $6,000 per month to lease its gym, but as an incentive, Hall gave Dunn half off the first year's lease costs, and one quarter off the second year's lease costs. Dunn's lease payments were as follows:
      

      
        Year 1: 12 × $3,000 = $36,000

        Year 2: 12 × $4,500 = $54,000

        Year 3: 12 × $6,000 = $72,000

        Year 4: 12 × $6,000 = $72,000

      
      
        Dunn's lease payments were due on the first day of the month, beginning on April 1, Year 1. What amount should Dunn report as lease expense in its monthly income statement for April, Year 3?`,
      choices: [
        `$4,500`,
        `$6,000`,
        `$3,000`,
        `$4,875`,
      ],
      correctIndex: 3,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">D. $4,875 is correct.</strong> Total payments of $234,000 spread evenly over the 48-month term give the same expense every month, including April of Year 3.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">A lessee recognizes the cost of an <strong style="color:var(--mx-navy)">operating lease</strong> on a <strong style="color:var(--mx-navy)">straight-line basis</strong> over the lease term (<strong style="color:var(--mx-navy)">ASC 842</strong>). Add up every payment required by the contract, including the discounted months, and divide by the number of months in the term.</p><p style="margin:0 0 18px">The <strong style="color:var(--mx-navy)">payment schedule is irrelevant</strong> to expense. Free rent, half-price months and step-up rents are <strong style="color:var(--mx-navy)">lease incentives</strong> that get averaged across the whole term. In the cheap early months the expense exceeds the cash paid and a liability builds; in the full-price later months the cash exceeds the expense and that liability unwinds.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The math</h3><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:8px 10px; margin-bottom:18px"><table style="border:0; border-collapse:collapse; width:100%"><tbody><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Year 1, 12 x $3,000</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$36,000</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Year 2, 12 x $4,500</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">54,000</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Year 3, 12 x $6,000</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">72,000</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Year 4, 12 x $6,000</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">72,000</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Total lease payments</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$234,000</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Lease term</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">48 months</td></tr><tr><td style="border:0; padding:11px 14px"><strong style="color:var(--mx-navy)">Monthly expense, $234,000 / 48</strong></td><td style="border:0; padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">$4,875</strong></td></tr></tbody></table></div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">Dunn's entry for April, Year 3</h3><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:8px 10px; margin-bottom:18px"><table style="border:0; border-collapse:collapse; width:100%"><tbody><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px"><strong style="color:var(--mx-navy)">Account</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Debit</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Credit</strong></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Lease expense</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$4,875</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Lease liability</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">1,125</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td></tr><tr><td style="border:0; padding:11px 14px 11px 40px">Cash</td><td style="border:0; padding:11px 14px; text-align:right"></td><td style="border:0; padding:11px 14px; text-align:right">$6,000</td></tr></tbody></table></div><p style="margin:0">Dunn writes a $6,000 check in April of Year 3, but only <strong style="color:var(--mx-navy)">$4,875 hits the income statement</strong>. The extra $1,125 reduces the liability created during the discounted first two years.</p></div>`,
    },
    {
      id: "5000",
      prompt: `On June 1 of the current year, a company entered into a real estate lease agreement for a new building. The lease is an operating lease and is fully executed on that day. According to the terms of the lease, payments of $28,900 per month are scheduled to begin on October 1 of the current year and to continue each month thereafter for 56 months. The lease term spans five years. The company has a calendar year end. What amount is the company's lease expense for the current calendar year?`,
      choices: [
        `$86,700`,
        `$161,838`,
        `$188,813`,
        `$202,300`,
      ],
      correctIndex: 2,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">C. $188,813 is correct.</strong> The total of all 56 payments is spread evenly over the full 60-month term, and seven of those months fall in the current year.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">Video walkthrough</h3><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:13px 18px; margin-bottom:18px"><video controls="controls" src="https://coursemaxwellcpareview.com/uploads/2025/07/07/1707-f.mp4" style="max-width:700px">Your browser does not support the video tag.</video></div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">An operating lease produces a single <strong style="color:var(--mx-navy)">straight-line lease cost</strong> (<strong style="color:var(--mx-navy)">ASC 842</strong>). Add every payment the lessee is required to make, divide by the number of months in the lease term, and recognize that amount each month beginning at the <strong style="color:var(--mx-navy)">commencement date</strong>. Here the lease is fully executed and the building is available on <strong style="color:var(--mx-navy)">June 1</strong>, so expense starts then, not when cash starts moving on October 1.</p><p style="margin:0 0 18px">The four-month <strong style="color:var(--mx-navy)">payment holiday</strong> is the trap. The term is five years, or <strong style="color:var(--mx-navy)">60 months</strong>, but only <strong style="color:var(--mx-navy)">56 payments</strong> are due. Free months do not reduce the expense in those months, they lower the monthly cost for every month of the term. From June through September expense accrues with no cash out, building the <strong style="color:var(--mx-navy)">lease liability</strong>; from October the $28,900 paid exceeds the monthly cost and draws that liability back down.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The math</h3><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:8px 10px; margin-bottom:18px"><table style="border:0; border-collapse:collapse; width:100%"><tbody><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Monthly payment</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$28,900</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Number of payments</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">56</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Total lease payments</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$1,618,400</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Lease term</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">60 months</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Monthly straight-line cost</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$26,973.33</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Months in current year, June to December</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">7</td></tr><tr><td style="border:0; padding:11px 14px"><strong style="color:var(--mx-navy)">Current year lease expense, $26,973.33 x 7</strong></td><td style="border:0; padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">$188,813</strong></td></tr></tbody></table></div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The entries</h3><p style="margin:0 0 8px">Each month, June through September:</p><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:8px 10px; margin-bottom:14px"><table style="border:0; border-collapse:collapse; width:100%"><tbody><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px"><strong style="color:var(--mx-navy)">Account</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Debit</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Credit</strong></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Lease expense</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$26,973.33</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td></tr><tr><td style="border:0; padding:11px 14px 11px 40px">Lease liability</td><td style="border:0; padding:11px 14px; text-align:right"></td><td style="border:0; padding:11px 14px; text-align:right">$26,973.33</td></tr></tbody></table></div><p style="margin:0 0 8px">Each month, October through December:</p><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:8px 10px; margin-bottom:12px"><table style="border:0; border-collapse:collapse; width:100%"><tbody><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px"><strong style="color:var(--mx-navy)">Account</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Debit</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Credit</strong></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Lease expense</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$26,973.33</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Lease liability</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$1,926.67</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td></tr><tr><td style="border:0; padding:11px 14px 11px 40px">Cash</td><td style="border:0; padding:11px 14px; text-align:right"></td><td style="border:0; padding:11px 14px; text-align:right">$28,900.00</td></tr></tbody></table></div><p style="margin:0">Cash outflow and lease expense differ every month of this lease, and only the expense line hits the income statement.</p></div>`,
    },
    {
      id: "4997",
      prompt: `Steam Co. acquired equipment under a finance lease for six years. Minimum lease payments were $60,000 payable annually at year-end. The interest rate was 5% with an annuity factor for six years of 5.0757. The present value of the payments was equal to the fair market value of the equipment. What amount should Steam report as interest expense at the end of the first year of the lease?`,
      choices: [
        `$0`,
        `$3,000`,
        `$15,227`,
        `$18,000`,
      ],
      correctIndex: 2,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">C. $15,227 is correct.</strong> First year interest is the 5% rate applied to the opening lease liability of $304,542.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">A finance lease is recorded at the <strong style="color:var(--mx-navy)">present value of the lease payments</strong>, discounted at the rate in the lease (<strong style="color:var(--mx-navy)">ASC 842</strong>). Multiply the annual payment by the annuity factor given, and that figure is both the <strong style="color:var(--mx-navy)">right-of-use asset</strong> and the <strong style="color:var(--mx-navy)">lease liability</strong> at commencement.</p><p style="margin:0 0 18px">Interest then follows the <strong style="color:var(--mx-navy)">effective interest method</strong>: opening liability times the rate. Because the payments are made at <strong style="color:var(--mx-navy)">year-end</strong>, nothing reduces the liability during year one, so the full $304,542 carries interest for the whole twelve months. The payment is applied to interest first, and only the <strong style="color:var(--mx-navy)">remainder reduces principal</strong>. Amortization of the asset is a separate expense and never enters this calculation.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The math</h3><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:8px 10px; margin-bottom:18px"><table style="border:0; border-collapse:collapse; width:100%"><tbody><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Annual payment</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$60,000</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Annuity factor, 6 years at 5%</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">5.0757</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Lease liability at commencement</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$304,542</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Discount rate</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">5%</td></tr><tr><td style="border:0; padding:11px 14px"><strong style="color:var(--mx-navy)">Interest expense, $304,542 x 5%</strong></td><td style="border:0; padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">$15,227</strong></td></tr></tbody></table></div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The entries</h3><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:8px 10px; margin-bottom:18px"><table style="border:0; border-collapse:collapse; width:100%"><tbody><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px"><strong style="color:var(--mx-navy)">At commencement</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Debit</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Credit</strong></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Right-of-use asset</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$304,542</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px 11px 40px">Lease liability</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$304,542</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px"><strong style="color:var(--mx-navy)">End of year one</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Interest expense</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$15,227</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Lease liability</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$44,773</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td></tr><tr><td style="border:0; padding:11px 14px 11px 40px">Cash</td><td style="border:0; padding:11px 14px; text-align:right"></td><td style="border:0; padding:11px 14px; text-align:right">$60,000</td></tr></tbody></table></div><p style="margin:0">Year two interest drops because the liability now stands at $259,769.</p></div>`,
    },
    {
      id: "5001",
      prompt: `On January 1, Year 1, Blaugh Co. signed a long-term lease for an office building. The terms of the lease required Blaugh to pay $10,000 annually, beginning December 30, Year 1, and continuing each year for 30 years. The lease qualifies as a finance lease. On January 1, Year 1, the present value of the lease payments is $112,500 at the 8 percent interest rate implicit in the lease. In Blaugh's December 31, Year 1, balance sheet, the lease liability should be:`,
      choices: [
        `$102,500`,
        `$111,500`,
        `$112,500`,
        `$290,000`,
      ],
      correctIndex: 1,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">B. $111,500 is correct.</strong> A full year of interest is added to the opening liability and the $10,000 payment is subtracted.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">Video walkthrough</h3><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:13px 18px; margin-bottom:18px"><video controls="controls" src="https://coursemaxwellcpareview.com/uploads/2025/07/07/1708-f.mp4" style="max-width:700px">Your browser does not support the video tag.</video></div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">A finance lease liability is carried at the <strong style="color:var(--mx-navy)">present value of the remaining payments</strong> and is unwound using the <strong style="color:var(--mx-navy)">effective interest method</strong> (<strong style="color:var(--mx-navy)">ASC 842</strong>). Each period: beginning balance, plus interest at the rate implicit in the lease, minus the cash paid.</p><p style="margin:0 0 18px">The payment is <strong style="color:var(--mx-navy)">not</strong> a straight $10,000 reduction of the liability. Interest accrued for the whole year on the $112,500 balance, so $9,000 of the payment is <strong style="color:var(--mx-navy)">interest expense</strong> and only $1,000 is <strong style="color:var(--mx-navy)">principal</strong>. Paying on December 30 rather than December 31 does not change the annual accrual here.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The math</h3><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:8px 10px; margin-bottom:18px"><table style="border:0; border-collapse:collapse; width:100%"><tbody><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Liability at January 1, Year 1</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$112,500</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Interest, $112,500 x 8%</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">9,000</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Payment, December 30, Year 1</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">(10,000)</td></tr><tr><td style="border:0; padding:11px 14px"><strong style="color:var(--mx-navy)">Liability at December 31, Year 1</strong></td><td style="border:0; padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">$111,500</strong></td></tr></tbody></table></div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The entries</h3><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:8px 10px; margin-bottom:18px"><table style="border:0; border-collapse:collapse; width:100%"><tbody><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px"><strong style="color:var(--mx-navy)">January 1, Year 1</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Debit</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">Credit</strong></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Right-of-use asset</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$112,500</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px 11px 40px">Lease liability</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$112,500</td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px"><strong style="color:var(--mx-navy)">December 30, Year 1</strong></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Interest expense</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">$9,000</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td></tr><tr><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px">Lease liability</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right">1,000</td><td style="border:0; border-bottom:1px solid var(--mx-rule); padding:11px 14px; text-align:right"></td></tr><tr><td style="border:0; padding:11px 14px 11px 40px">Cash</td><td style="border:0; padding:11px 14px; text-align:right"></td><td style="border:0; padding:11px 14px; text-align:right">$10,000</td></tr></tbody></table></div><p style="margin:0">Undiscounted future payments never appear on the balance sheet, and the opening present value is stale once a year of interest and one payment have run through it.</p></div>`,
    },
  ],
};
